import type { NextConfig } from "next";
// Generated by scripts/migrate.py: recovered URLs whose content now lives at another URL
import migrationRedirects from "./src/content/redirects.json";

const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
  // The original WordPress site used trailing-slash URLs (/about-us-3/, /2025/08/11/slug/); keep them.
  trailingSlash: true,
  images: {
    qualities: [75, 90],
  },
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  async redirects() {
    // WooCommerce cart/checkout/account pages cannot work without the original store backend.
    // Old links to them land on the IT Training catalog instead of a 404.
    const commerce = ["cart", "cart-2", "cart-3", "checkout", "checkout-2", "wishlist", "compare", "my-account", "dashboard"].map(
      (p) => ({ source: `/${p}/:rest*`, destination: "/shop/", permanent: true }),
    );
    const migrated = migrationRedirects.map(({ source, destination }) => ({
      source: source.replace(/\/$/, ""), // matched before the trailing-slash redirect, with or without slash
      destination,
      permanent: true,
    }));
    return [...commerce, ...migrated];
  },
};

export default nextConfig;
